import React, { useState, useRef } from "react";
import "./App.css";

function App() {
  const [disease, setDisease] = useState("");
  const [intent, setIntent] = useState("");
  const [location, setLocation] = useState("");
  const [mode, setMode] = useState("fast");

  const [summary, setSummary] = useState("");
  const [publications, setPublications] = useState([]);
  const [trials, setTrials] = useState([]);
  const [loading, setLoading] = useState(false);

  const summaryRef = useRef(null);

  // 🚀 SEARCH FUNCTION
  const handleSearch = async () => {
    if (!disease && !intent) {
      alert("Enter disease or question");
      return;
    }

    setLoading(true);

    // ⚡ FAST MODE (instant)
    if (mode === "fast") {
      setSummary(`Condition Overview:
${disease || "General condition"}

• Early diagnosis is important  
• Treatment varies by severity  
• Lifestyle + medication helps  

(Use Deep Mode for research data)`);

      setPublications([]);
      setTrials([]);
      setLoading(false);
      return;
    }

    // 🔬 DEEP MODE (backend)
    try {
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), 12000);

      const res = await fetch("http://127.0.0.1:8000/analyze", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          disease,
          intent,
          location,
        }),
        signal: controller.signal,
      });

      clearTimeout(timeout);

      const data = await res.json();
      console.log("DATA:", data);

      // ✅ IMPORTANT FIX HERE
      setSummary(data.insights || "No insights found");
      setPublications(data.publications || []);
      setTrials(data.clinical_trials || []);

      // scroll to result
      setTimeout(() => {
        summaryRef.current?.scrollIntoView({ behavior: "smooth" });
      }, 200);

    } catch (err) {
      console.error(err);
      setSummary("⚠️ Backend slow or error. Try Fast Mode.");
    }

    setLoading(false);
  };

  return (
    <div className="app">

      {/* LEFT PANEL */}
      <div className="sidebar">
        <h1>Curalink X</h1>
        <p>AI Medical Research Copilot</p>

        <input
          placeholder="e.g., diabetes"
          value={disease}
          onChange={(e) => setDisease(e.target.value)}
        />

        <div className="mode-toggle">
          <button onClick={() => setMode("fast")}>⚡ Fast</button>
          <button onClick={() => setMode("deep")}>🔬 Deep</button>
        </div>

        <div className="stats">
          <p>Research papers: {publications.length}</p>
          <p>Clinical trials: {trials.length}</p>
          <p>Risk confidence: 0%</p>
        </div>
      </div>

      {/* CENTER */}
      <div className="main">
        <h1>OpenAI reasoning copilot</h1>

        <textarea
          placeholder="Ask your medical research question..."
          value={intent}
          onChange={(e) => setIntent(e.target.value)}
        />

        <button onClick={handleSearch}>
          {loading ? "⏳ Thinking..." : "Send message"}
        </button>

        <input
          placeholder="Location"
          value={location}
          onChange={(e) => setLocation(e.target.value)}
        />

        {/* ✅ SUMMARY */}
        {summary && (
          <div className="summary" ref={summaryRef}>
            <h3>AI Summary</h3>
            {summary.split("\n").map((line, i) => (
              <p key={i}>{line}</p>
            ))}
          </div>
        )}
      </div>

      {/* RIGHT PANEL */}
      <div className="right">

        <div className="card">
          <h3>Research papers</h3>
          {publications.length === 0 ? (
            <p>No publication cards available yet</p>
          ) : (
            publications.map((p, i) => (
              <div key={i}>
                <h4>{p.title}</h4>
                <a href={p.link} target="_blank" rel="noreferrer">
                  View Paper
                </a>
              </div>
            ))
          )}
        </div>

        <div className="card">
          <h3>Clinical trials</h3>
          {trials.length === 0 ? (
            <p>No clinical trials found</p>
          ) : (
            trials.map((t, i) => (
              <div key={i}>
                <h4>{t.title}</h4>
                <p>{t.status}</p>
              </div>
            ))
          )}
        </div>

      </div>

    </div>
  );
}

export default App;
